defineProps<{advice:EarlyHoldAdvice;focused?:string|null}>();
defineEmits<{stage:[number|null];focus:[string|null]}>();
const name=(id:string)=>dataset.characterById(id)?.display_name??'待更新';
</script>
<template><section class="early-holds" data-early-advisor>
  <header><h2>先留好牌</h2><span v-if="advice.stageEstimated" title="尚未识别到回合阶段，按当前等级估计；可手动切换。">按人口参考</span><nav><button v-for="n in [2,3,4,5]" :key="n" :class="{active:n===advice.stage}" :data-early-stage="n" @click="$emit('stage',n)">阶段 {{ n }}</button><button title="跟随对局阶段" aria-label="自动选择阶段" @click="$emit('stage',null)">↻</button></nav></header>
